"""mcp.py - 极简 MCP（Model Context Protocol）stdio 客户端。

从 `.xsh/mcp.json` 读取服务器定义（{"servers": {"name": {"command": "...", "args": [...]}}}），
以行分隔 JSON-RPC 与其通信，列出/调用其工具。任何失败都优雅降级：跳过该服务器。
"""
import json, subprocess
from pathlib import Path

_PROTOCOL_VERSION = "2024-11-05"
_MAX_LINE = 1_000_000

class McpError(RuntimeError): pass

class McpClient:
    def __init__(self, name, command, args, cwd, timeout=30):
        self.name=name; self.command=command; self.args=list(args); self.cwd=Path(cwd); self.timeout=timeout
        self.process=None; self._id=0
    def start(self):
        self.process = subprocess.Popen([self.command, *self.args], cwd=self.cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, bufsize=1)
    def _send(self, message): 
        assert self.process and self.process.stdin
        self.process.stdin.write(json.dumps(message)+"\n"); self.process.stdin.flush()
    def _read_response(self, request_id):
        assert self.process and self.process.stdout
        while True:
            line = self.process.stdout.readline()
            if not line: raise McpError("server closed the connection")
            line=line.strip()
            if not line: continue
            try: message = json.loads(line)
            except ValueError: continue
            if message.get("id") == request_id:
                if "error" in message: raise McpError(str(message["error"]))
                return message.get("result", {})
    def request(self, method, params):
        self._id += 1
        self._send({"jsonrpc":"2.0","id":self._id,"method":method,"params":params})
        return self._read_response(self._id)
    def notify(self, method, params):
        self._send({"jsonrpc":"2.0","method":method,"params":params})
    def initialize(self):
        self.request("initialize", {"protocolVersion": _PROTOCOL_VERSION, "capabilities": {}, "clientInfo": {"name":"xsh","version":"0.1"}})
        self.notify("notifications/initialized", {})
    def list_tools(self):
        result = self.request("tools/list", {})
        return result.get("tools", []) if isinstance(result, dict) else []
    def call_tool(self, name, arguments):
        result = self.request("tools/call", {"name": name, "arguments": arguments})
        return _flatten(result)
    def close(self):
        if self.process is not None:
            try: self.process.stdin and self.process.stdin.close()
            except OSError: pass
            try: self.process.terminate()
            except OSError: pass
            self.process=None

def _flatten(result):
    if not isinstance(result, dict): return str(result)
    parts=[]
    for item in result.get("content", []) or []:
