def _session_check(path: Path) -> Check:
    if not path.is_file():
        return ("session", WARN, "no session file to check")
    try:
        from xsh.session import Session
        session = Session.load(path)
    except Exception as error:  # 损坏的会话文件应被显式标出，便于恢复前发现
